class Solution {
public:
    bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
        vector<vector<int>> g(n + 1);
        for (const auto& p : dislikes) {
            int a = p[0], b = p[1];
            g[a].push_back(b);
            g[b].push_back(a);
        }
        vector<int> colour(n + 1, 0); // 0 = uncoloured, 1 or -1 = two groups
        queue<int> q;
        for (int i = 1; i <= n; ++i) {
            if (colour[i] != 0) continue;
            colour[i] = 1;
            q.push(i);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : g[u]) {
                    if (colour[v] == 0) {
                        colour[v] = -colour[u];
                        q.push(v);
                    } else if (colour[v] == colour[u]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
};
